import { test, expect } from '@playwright/test';

test.describe('Email Field Inline Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display inline validation errors as user types in email field', async ({ page }) => {
    // Locate email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();

    // Type a valid email
    await emailInput.fill('test@example.com');
    await expect(emailInput).toHaveValue('test@example.com');

    // Verify no validation error is displayed
    const emailError = page.getByText('Email is required');
    await expect(emailError).not.toBeVisible();

    // Type an invalid email
    await emailInput.fill('invalid-email');

    // Verify validation error is displayed
    await expect(emailError).toBeVisible();

    // Verify error message is visible
    const errorMessage = page.getByText('Please enter a valid email address');
    await expect(errorMessage).toBeVisible();

    // Verify error styling is applied
    const errorClass = emailInput.getByRole('textbox').first().evaluate((el) => el.classList.contains('error'));
    await expect(errorClass).toBe(true);

    // Verify email input still has focus
    await expect(emailInput).toHaveFocus();
  });

  test('should clear validation errors when email is corrected', async ({ page }) => {
    // Locate email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();

    // Type an invalid email
    await emailInput.fill('invalid-email');
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    // Correct the email
    await emailInput.fill('valid.email@example.com');

    // Verify validation error is cleared
    await expect(emailError).not.toBeVisible();

    // Verify email input is no longer styled as error
    const errorClass = emailInput.getByRole('textbox').first().evaluate((el) => el.classList.contains('error'));
    await expect(errorClass).toBe(false);

    // Verify email input has no error styling
    const errorStyles = emailInput.getByRole('textbox').first().evaluate((el) => el.style.borderColor);
    await expect(errorStyles).toBe('transparent');

    // Verify email input still has focus
    await expect(emailInput).toHaveFocus();
  });
});
